from lib import *
S = SS('w43')
steps = [
    step("listen(backlog) 里的 backlog 到底有多大:服务端 listen(N) 但从不 accept,客户端一口气发起 N+20 个 connect,等 1 秒数连上的个数。kern.ipc.somaxconn = 128。listen(0):发起 20 个,连上 20 个,netstat -L(qlen/incqlen/maxqlen)显示 20/0/128——backlog 为 0 被当成了默认上限 128;listen(1):连上 1 个,maxqlen = 1;listen(5):连上 5 个;listen(10):10 个;listen(50):50 个;listen(128):128 个;listen(1000):发起 320 个只连上 128 个,maxqlen 被截成 128。也就是说在这台机器上全连接队列正好容纳 N 个(没有“N + 1”的多出一个),上限被 somaxconn 卡在 128。", t=tl(S(1)), mark=lidx(S(1), 'listen(   0)', 'listen(1000)'), done=lidx(S(1), 'kern.ipc.somaxconn', 'listen(   1)', 'listen(   5)', 'listen(  10)', 'listen(  50)', 'listen( 128)'), b=bars([['listen(1) · 连上', 1, '1'], ['listen(5) · 连上', 5, '5'], ['listen(50) · 连上', 50, '50'], ['listen(128) · 连上', 128, '128'], ['listen(1000) · 连上', 128, '128(被 somaxconn 截断)']], 128, mark=[4], done=[0, 1, 2, 3]), kv=KV([['listen(N)', '全连接队列正好容纳 N 个'], ['listen(0)', '当成默认 128'], ['listen(1000)', '被 somaxconn 截到 128'], ['netstat -Lan', 'qlen/incqlen/maxqlen']], ['listen(1000)'])),
    step("队列满了以后新连接怎么办:服务端 listen(5) 不 accept,用 5 个阻塞 connect 塞满(netstat -L 显示 5/0/5)。再来 3 个客户端,每个的 connect() 都“成功”(用时 0.14、0.17、0.33 ms),但随后 send 报 BrokenPipeError [Errno 32]、recv 报 ConnectionResetError [Errno 54];线上是 SYN → SYN+ACK → ACK → 服务端 RST。也就是说队列满时服务端照常回 SYN-ACK,客户端以为连上了,收到第三个 ACK 时服务端发现放不下才发 RST 丢掉连接。这和 Linux 常见的“队列满就丢 SYN、客户端不停重传 SYN”不同。netstat -s -p tcp 的“listen queue overflow”在这段时间增加了 0,但这台机器上该命令的 TCP 计数全是 0(连“发出的包”都是 0),不能用来对账。服务端 accept 了 1 个腾出位置后,再来的客户端连上、能发数据、没有被重置。", t=tl(S(2)), mark=lidx(S(2), '队列已满时的第 1 个客户端', '队列已满时的第 2 个客户端', '队列已满时的第 3 个客户端'), done=lidx(S(2), '塞满以后', 'netstat -L 此刻', '服务端 accept 了 1 个'), b=bars([['connect() 返回(客户端)', 0.14, '0.14 ms · 成功'], ['随后 send', 0, 'EPIPE'], ['随后 recv', 0, 'ECONNRESET']], 0.2, mark=[1, 2], done=[0, 3]), kv=KV([['队列满时的握手', 'SYN → SYN+ACK → ACK → RST'], ['客户端', 'connect 成功,send / recv 才报错'], ['腾出位置后', '正常连上,不被重置']], ['队列满时的握手'])),
    step("somaxconn 上限:listen(1000) 之后一口气发起 400 个 connect,只连上 128 个,netstat -L 显示 128/0/128,maxqlen 被截到了 128,正好是 somaxconn。想要更大的全连接队列,必须同时调大 kern.ipc.somaxconn(需要 root)和 listen 的参数。", t=tl(S(3)), mark=lidx(S(3), 'listen(1000):400'), done=lidx(S(3), 'netstat -L:qlen'), b=bars([['listen 参数', 1000, '1000'], ['实际 maxqlen', 128, '128']], 1000, mark=[1], done=[0]), kv=KV([['listen(1000)', '400 个 connect,连上 128 个'], ['maxqlen', '= somaxconn = 128']], ['maxqlen'])),
    step("半连接队列(SYN_RCVD):netlab 加 300 ms 单向延迟,第三个 ACK 要 300 ms 才到服务端,这段时间服务端处于 SYN_RCVD。发起 40 个并发连接后,netstat -L 的 qlen/incqlen/maxqlen 随时间是:6 ms 时 0/0/128、235 ms 时 0/0/128、472 ms 和 699 ms 时 40/40/128、928 ms、1150 ms 和 1388 ms 时 40/0/128:incqlen(未完成握手的半连接)最大 40,握手完成后降回 0,而 qlen 一直是 40——握手期间它就已经把这 40 个连接算在内了,为什么这样没有深究。所以有两个队列:半连接队列(SYN_RCVD)和全连接队列(已 ESTABLISHED、等应用 accept);listen 的 backlog 管的是后者。", t=tl(S(4)), mark=lidx(S(4), '发起 40 个并发连接后', 'incqlen 最大'), done=lidx(S(4), '所以有两个队列'), b=bars([['incqlen 最大(半连接)', 40, '40'], ['qlen 最大', 40, '40'], ['maxqlen', 128, '128']], 128, mark=[0], done=[1, 2]), kv=KV([['SYN_RCVD 期间', 'incqlen = 40'], ['握手完成后', 'incqlen → 0,qlen 仍是 40'], ['backlog', '管全连接队列']], ['backlog'])),
]
A = mkartw('w43', 43, '网络协议,TCP,半连接队列,全连接队列,backlog,somaxconn,netstat,真实验证,动画演示',
    'macOS 的 listen(N) 让全连接队列正好容纳 N 个(上限 somaxconn = 128);队列满时服务端仍回 SYN-ACK,客户端 connect 成功但随后被 RST(与 Linux 丢 SYN 不同);netstat -L 的 qlen/incqlen/maxqlen。',
    'listen 的 backlog 到底限制什么?队列满了新连接会怎样?半连接和全连接队列怎么区分?这篇用 netstat -L 逐项量,并抓包发现 macOS 在全连接队列满时的做法和 Linux 不一样:握手照常完成,然后被 RST。',
    [('N 个', 'listen(N) 之后不 accept,全连接队列实际容纳的连接数;listen(1000) 被截成 128'), ('SYN → SYN+ACK → ACK → RST', '全连接队列满时新连接的线上过程:客户端 connect() 成功,随后 send 得 EPIPE、recv 得 ECONNRESET'), ('40 / 40 / 128', '40 个并发握手期间 netstat -L 显示的 qlen/incqlen/maxqlen')],
    [('backlog 的含义', '<p>listen(N) 之后,全连接队列正好容纳 N 个(0 当成默认值 128),上限被 kern.ipc.somaxconn(128)卡住。</p>'),
     ('队列满了', '<p>macOS 不丢 SYN:仍回 SYN-ACK,客户端 connect 成功;第三个 ACK 到达时才发现放不下,用 RST 丢掉。客户端的第一次读写才会报错。netstat -s 的 TCP 计数在这台机器上全是 0,不可用。</p>'),
     ('两个队列', '<p>半连接队列(SYN_RCVD)与全连接队列(ESTABLISHED、等 accept)。netstat -Lan 显示 qlen/incqlen/maxqlen。</p>'),
     ('排查', '<p>客户端偶尔 “connection reset by peer” 却没有任何服务端日志,可以先看 netstat -Lan 里这个端口的队列是不是满的。</p>')],
    steps,
    [ENV_W + '。全部在 lo0 上做;第四节的延迟由 netlab 注入;客户端用非阻塞 connect 一口气发起并在 1 秒后统计,个数用 select + SO_ERROR 判断,可能受时序影响一两个;队列满时的行为是 macOS 实测,其它系统不同',
     '没有验证:tcp_syncookies / syncache 的上限(下一篇 SYN Flood 再看);队列满时在 en0 真实网络上的表现;qlen 在握手期间就包含半连接的原因;net.inet.tcp 里和队列有关的其它参数;应用 accept() 很慢时连接的超时行为'],
    '半连接与全连接队列')
